// Generates the push service worker's runtime config from the Angular single sources of truth.
//
// The service worker (public/push/sw-push.js) is a STATIC asset — it can't import Angular constants at
// runtime, and hardcoding them in two places drifts. This script reads from src/app/services and emits
// public/push/sw-config.js, which sw-push.js loads via `importScripts('./sw-config.js')`. npm runs it
// automatically as `prebuild` before every `ng build`. Commit the generated file (deterministic) so a fresh
// checkout is self-consistent; prebuild keeps it fresh.
//
// Mirrored values:
//  - API_PREFIX (constants.ts) → self.__SOMS_API_PREFIX__  — the /api/v1 endpoint prefix.
//  - SOMS_NOTIF_MSG (sw-notif-protocol.ts) → self.__SOMS_NOTIF_MSG__ — the SW↔page postMessage `type`
//    discriminants (a typo there is a SILENT breakage, so the two sides share one source).
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..');
const constantsPath = join(root, 'src/app/services/constants.ts');
const protocolPath = join(root, 'src/app/services/sw-notif-protocol.ts');
const outPath = join(root, 'public/push/sw-config.js');

const src = readFileSync(constantsPath, 'utf8');
const m = src.match(/export\s+const\s+API_PREFIX\s*=\s*(['"])([^'"]+)\1/);
if (!m) {
  // Fail loud: a silent skip would leave the SW reading a stale/missing config. If you renamed or moved
  // API_PREFIX, update this regex to match the new declaration.
  throw new Error(
    `[gen-sw-config] could not find 'export const API_PREFIX = "..."' in ${constantsPath}`,
  );
}
const prefix = m[2];

// Extract the SW↔page message `type` discriminants from the protocol source.
const proto = readFileSync(protocolPath, 'utf8');
const dismiss = proto.match(/DISMISS:\s*(['"])([^'"]+)\1/);
const open = proto.match(/OPEN:\s*(['"])([^'"]+)\1/);
const claim = proto.match(/CLAIM:\s*(['"])([^'"]+)\1/);
if (!dismiss || !open || !claim) {
  throw new Error(
    `[gen-sw-config] could not find DISMISS/OPEN/CLAIM string literals in ${protocolPath}`,
  );
}

const body = `// AUTO-GENERATED by scripts/gen-sw-config.mjs — do NOT edit by hand; \`npm run prebuild\` regenerates
// it before every build. Sources: src/app/services/constants.ts (API_PREFIX) +
// src/app/services/sw-notif-protocol.ts (SOMS_NOTIF_MSG). The push service worker loads this via
// importScripts so its endpoint + SW↔page message types stay in lockstep with the Angular app.
self.__SOMS_API_PREFIX__ = ${JSON.stringify(prefix)};
self.__SOMS_NOTIF_MSG__ = { DISMISS: ${JSON.stringify(dismiss[2])}, OPEN: ${JSON.stringify(open[2])}, CLAIM: ${JSON.stringify(claim[2])} };
`;
writeFileSync(outPath, body);
console.log(
  `[gen-sw-config] wrote ${outPath} (API_PREFIX=${JSON.stringify(prefix)}, ` +
    `NOTIF_MSG.D=${JSON.stringify(dismiss[2])}, .O=${JSON.stringify(open[2])}, .C=${JSON.stringify(claim[2])})`,
);
